import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from 'expo-audio';

import { usePreferencesStore } from '@/state/preferences';

// Generated by scripts/generate-sounds.mjs.
const sources = {
  /** A link between two facts was confirmed. */
  link: require('@/assets/sounds/link.wav'),
  /** A comparison or report didn't hold up. */
  miss: require('@/assets/sounds/miss.wav'),
  /** The final report was accepted. */
  solved: require('@/assets/sounds/solved.wav'),
} as const;

export type SoundName = keyof typeof sources;

const players: Partial<Record<SoundName, AudioPlayer>> = {};
let modeSet = false;

/**
 * Play a UI sound if the player has sounds turned on. Sounds respect the silent switch, mix with
 * whatever else is playing, and never throw: a sound failing must not interrupt play.
 */
export function playSound(name: SoundName) {
  if (!usePreferencesStore.getState().sound) return;
  try {
    if (!modeSet) {
      modeSet = true;
      setAudioModeAsync({ playsInSilentMode: false, interruptionMode: 'mixWithOthers' }).catch(
        (e: unknown) => console.warn('[sound] Could not set audio mode', e),
      );
    }
    const player = (players[name] ??= createAudioPlayer(sources[name]));
    player
      .seekTo(0)
      .then(() => player.play())
      .catch((e: unknown) => console.warn(`[sound] Could not play ${name}`, e));
  } catch (e) {
    console.warn(`[sound] Could not play ${name}`, e);
  }
}
